package com.riverguard.v2;

import org.json.JSONArray;
import org.json.JSONObject;
import org.junit.Test;
import java.time.Instant;
import static org.junit.Assert.*;
import static com.riverguard.v2.PhoneValidation.*;

public class SignalEvaluatorTest {
    private static final long NOW=1792641600000L;
    private JSONObject row(long age,int revision,double height) {
        JSONObject settings=object("{\"enabled\":{\"ph\":true,\"turbidity\":true,\"temperature\":true,\"water_level\":true},\"ph\":[{\"mv\":1500,\"value\":4},{\"mv\":2000,\"value\":7}],\"turbidity\":[{\"mv\":1500,\"value\":100},{\"mv\":2500,\"value\":0}],\"level\":{\"reference\":200,\"minimum\":25,\"maximum\":450},\"temperature_offset\":0,\"verified\":true}");
        JSONObject payload=json("sample_id","sample-"+age,"device_id","one","config_revision",revision,"raw",json("ph_mv",2000,"turbidity_mv",2400,"temperature_c",27,"distance_cm",200-height),"sensor_health",new JSONObject());
        return json("id",NOW-age,"deviceId","one","timestamp",Instant.ofEpochMilli(NOW-age).toString(),"receivedAt",Instant.ofEpochMilli(NOW).toString(),"payload",payload,"settings",settings);
    }
    private JSONObject evaluate(JSONArray rows){return SignalEvaluator.evaluate(rows,json("elevated",70,"warning",100,"rise_limit",10),NOW);}
    private boolean signal(JSONObject result,String kind){JSONArray signals=result.optJSONArray("signals");for(int i=0;i<signals.length();i++)if(signals.optJSONObject(i).optString("kind").equals(kind))return true;return false;}
    @Test public void healthySnapshotHasNoEnvironmentalAlert(){JSONObject result=evaluate(new JSONArray().put(row(0,1,40)));assertTrue(result.optBoolean("fresh"));assertEquals(0,result.optJSONArray("signals").length());}
    @Test public void highWaterSurvivesAnotherProbeFaultAndHasPriority(){JSONObject row=row(0,1,120);put(row.optJSONObject("payload").optJSONObject("sensor_health"),"ph","missing");JSONObject result=evaluate(new JSONArray().put(row));assertTrue(signal(result,"water_warning"));assertTrue(signal(result,"sensor_health"));assertEquals("water_warning",result.optJSONArray("signals").optJSONObject(0).optString("kind"));}
    @Test public void futureAndStaleDataCannotTriggerNewCurrentWaterAlerts(){for(long age:new long[]{31000,-6000}){JSONObject result=evaluate(new JSONArray().put(row(age,1,120)));assertFalse(result.optBoolean("fresh"));assertFalse(signal(result,"water_warning"));assertTrue(signal(result,"connection"));}}
    @Test public void rawFaultAndUnknownCalibrationCannotInventHeight(){JSONObject row=row(0,1,120);put(row.optJSONObject("payload").optJSONObject("sensor_health"),"water_level","out_of_range");assertFalse(signal(evaluate(new JSONArray().put(row)),"water_warning"));put(row,"settings",null);assertFalse(signal(evaluate(new JSONArray().put(row)),"water_warning"));}
    @Test public void risingRequiresFiveSameRevisionSamplesOverEightSeconds(){JSONArray rows=new JSONArray();for(int i=0;i<5;i++)rows.put(row(i*2000,1,60-i));JSONObject result=evaluate(rows);assertEquals(30,result.optDouble("rate"),.001);assertTrue(signal(result,"water_rise"));put(rows.optJSONObject(4).optJSONObject("payload"),"config_revision",2);assertTrue(evaluate(rows).isNull("rate"));}
    @Test public void missingSampleAndGapBreakRise(){JSONArray rows=new JSONArray();for(int i=0;i<5;i++)rows.put(row(i*2000,1,60-i));put(rows.optJSONObject(2).optJSONObject("payload").optJSONObject("sensor_health"),"water_level","timeout");assertTrue(evaluate(rows).isNull("rate"));rows=new JSONArray();for(int i=0;i<5;i++)rows.put(row(i*40000,1,60-i));assertTrue(evaluate(rows).isNull("rate"));}
    @Test public void unavailableRawAndNoExtrapolationStayUnknown(){JSONObject row=row(0,1,40);put(row.optJSONObject("payload").optJSONObject("raw"),"ph_mv",3000);assertNull(new SignalEvaluator.Reading(row,NOW).values[0]);put(row.optJSONObject("payload").optJSONObject("raw"),"distance_cm",20);assertNull(new SignalEvaluator.Reading(row,NOW).values[3]);}
    @Test public void zeroUsableWaterHeightCannotBeCalibratedOrInterpreted(){JSONObject row=row(0,1,40),settings=row.optJSONObject("settings");put(settings.optJSONObject("level"),"reference",25);put(row.optJSONObject("payload").optJSONObject("raw"),"distance_cm",25);try{PhoneValidation.settings(settings);fail("Degenerate tank geometry must be rejected");}catch(Problem expected){assertEquals(422,expected.status);}assertNull(new SignalEvaluator.Reading(row,NOW).values[3]);put(settings.optJSONObject("level"),"reference",26);assertNotNull(PhoneValidation.settings(settings));assertEquals(1,new SignalEvaluator.Reading(row,NOW).values[3],.001);}
    @Test public void watchSettingsCannotSilentlyAcceptInvalidNumbers(){try{SignalEvaluator.watch(json("elevated",100,"warning",70,"rise_limit",10));fail();}catch(Problem expected){assertEquals(422,expected.status);}assertEquals(70,SignalEvaluator.watch(json("elevated",70,"warning",100,"rise_limit",10)).optInt("elevated"));}
    @Test public void ledgerDeduplicatesAcrossSerializationAndRequiresNewHealthySamples(){JSONObject result=evaluate(new JSONArray().put(row(0,1,120)));JSONObject first=AlertLedger.apply(null,result,NOW);assertEquals(1,first.optJSONArray("events").length());JSONObject repeat=AlertLedger.apply(object(first.optJSONObject("state").toString()),result,NOW+2000);assertEquals(0,repeat.optJSONArray("events").length());JSONObject healthy=evaluate(new JSONArray().put(row(0,1,40)));put(healthy,"sample","healthy-1");JSONObject one=AlertLedger.apply(repeat.optJSONObject("state"),healthy,NOW);assertEquals(0,one.optJSONArray("events").length());one=AlertLedger.apply(one.optJSONObject("state"),healthy,NOW);assertEquals(0,one.optJSONArray("events").length());put(healthy,"sample","healthy-2");one=AlertLedger.apply(one.optJSONObject("state"),healthy,NOW);put(healthy,"sample","healthy-3");one=AlertLedger.apply(one.optJSONObject("state"),healthy,NOW);assertEquals("recovered",one.optJSONArray("events").optJSONObject(0).optString("phase"));}
}
